// Miniature checkpointer: snapshots per step, resume by thread (playground logic)
function makeCheckpointer() {
  const store = new Map(); // thread_id -> array of {step, state, next}
  return {
    save(thread, step, state, next) {
      if (!store.has(thread)) store.set(thread, []);
      store.get(thread).push({ step, state: JSON.parse(JSON.stringify(state)), next });
    },
    load(thread) { return store.get(thread) || []; },
    resumeState(thread) {
      const hist = store.get(thread) || [];
      return hist.length ? hist[hist.length - 1] : null;
    },
  };
}
// Deep-copy on save: later mutations must not rewrite history.

